//! Write a *synthetic* game directory (placeholder EGATILES.BIN + MAP.BIN
//! generated by `u1_assets::demo`) for testing the `--game-dir` code path
//! without original files. Output contains no Origin data.
//! `cargo run -p u1-assets --example write_synthetic_gamedir -- <dir>`
fn main() {
    let dir = std::env::args().nth(1).expect("usage: write_synthetic_gamedir <dir>");
    std::fs::create_dir_all(&dir).unwrap();
    let p = std::path::Path::new(&dir);
    std::fs::write(p.join("EGATILES.BIN"), u1_assets::demo::demo_egatiles_bin()).unwrap();
    std::fs::write(p.join("MAP.BIN"), u1_assets::demo::demo_map_bin(7)).unwrap();
    println!("wrote synthetic EGATILES.BIN and MAP.BIN to {dir}");
}
